INSERT INTO public.livros_ebooks (titulo_livro, subtitulo, capa_url, pdf_url, sinopse, total_capitulos) VALUES ('Vitória na Família: Princípios Inabaláveis para Restaurar o seu Lar', 'Um guia bíblico prático para reconciliar relacionamentos e edificar um lar segundo o coração de Deus', 'https://exemplo.com/capas/vitoria-na-familia.jpg', 'https://exemplo.com/pdfs/vitoria-na-familia.pdf', 'Em um tempo de crescente fragmentação familiar, este livro apresenta princípios bíblicos sólidos para restaurar casamentos, curar feridas entre pais e filhos e reconstruir a unidade do lar. Com linguagem acessível e exemplos práticos, o autor conduz o leitor por um caminho de arrependimento, perdão e renovação de aliança, mostrando que nenhuma família está além do alcance da graça de Deus.', 12);
INSERT INTO public.livros_ebooks (titulo_livro, subtitulo, capa_url, pdf_url, sinopse, total_capitulos) VALUES ('Guerra Espiritual & Libertação: Vencendo as Batalhas Invisíveis pelo Poder da Palavra', 'Estratégias bíblicas para identificar, resistir e vencer as forças espirituais que atuam contra sua vida', 'https://exemplo.com/capas/guerra-espiritual-libertacao.jpg', 'https://exemplo.com/pdfs/guerra-espiritual-libertacao.pdf', 'Existe uma batalha real acontecendo além do que os olhos podem ver. Este livro revela, à luz das Escrituras, como reconhecer as táticas do inimigo, romper ciclos de opressão e viver em liberdade plena através da autoridade da Palavra de Deus. Um manual de combate espiritual para crentes que desejam vencer, e não apenas sobreviver.', 12);
INSERT INTO public.livros_ebooks (titulo_livro, subtitulo, capa_url, pdf_url, sinopse, total_capitulos) VALUES ('Fundamentos da Fé Pentecostal: Da Conversão ao Discipulado de Alto Impacto', 'Um itinerário bíblico para novos convertidos crescerem em maturidade e propósito no Espírito', 'https://exemplo.com/capas/fundamentos-fe-pentecostal.jpg', 'https://exemplo.com/pdfs/fundamentos-fe-pentecostal.pdf', 'Da experiência da nova vida em Cristo à formação de discípulos que impactam seu meio, este livro apresenta os pilares essenciais da fé pentecostal de forma clara e edificante. Aborda conversão, batismo, o batismo com o Espírito Santo, os dons espirituais e a vida de santidade, equipando o leitor para uma jornada de crescimento sólido e serviço frutífero no Reino de Deus.', 12);
