INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (53, 'Dia 53: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 40:31', 'Os que esperam no Senhor renovarão as suas forças; subirão com asas como águias.', 'A espera em Deus não é tempo perdido; é fortalecimento de asas para voos mais altos. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 40:31 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 40:31. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_053.mp3') ON CONFLICT (dia_ano) DO NOTHING;
