INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (76, 'Dia 76: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 41:10', 'Não temas, porque eu sou contigo; não te assombres, porque eu sou o teu Deus.', 'A solidão se dissipa quando entendemos que a destra fiel de Deus nos sustenta. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 41:10 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 41:10. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_076.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (77, 'Dia 77: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 53:5', 'Pelas suas pisaduras fomos sarados.', 'Na cruz de Cristo, não apenas os pecados foram pagos, mas a cura de nossas feridas foi selada. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 53:5 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 53:5. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_077.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (78, 'Dia 78: O Poder de Jeremias no Seu Altar', 'Jeremias', 'Jr 29:11', 'Pois eu bem sei os planos que tenho para vós, diz o Senhor; planos de paz e não de mal.', 'O seu futuro não está entregue ao acaso; está desenhado pelas mãos do Pai. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Jr 29:11 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Jr 29:11. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_078.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (79, 'Dia 79: O Poder de Mateus no Seu Altar', 'Mateus', 'Mt 6:33', 'Buscai primeiro o reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.', 'Alinhe as suas prioridades: coloque Deus no topo e veja as bênçãos se encaixarem. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Mt 6:33 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Mt 6:33. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_079.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (80, 'Dia 80: O Poder de Mateus no Seu Altar', 'Mateus', 'Mt 11:28', 'Vinde a mim, todos os que estais cansados e oprimidos, e eu vos aliviarei.', 'Jesus não te convida para uma religião pesada, Ele te convida para o descanso da graça. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Mt 11:28 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Mt 11:28. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_080.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (81, 'Dia 81: O Poder de João no Seu Altar', 'João', 'Jo 14:6', 'Eu sou o caminho, e a verdade, e a vida; ninguém vem ao Pai senão por mim.', 'Jesus não é uma das opções; Ele é o único caminho seguro para a eternidade. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Jo 14:6 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Jo 14:6. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_081.mp3') ON CONFLICT (dia_ano) DO NOTHING;
