INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (83, 'Dia 83: O Poder de Romanos no Seu Altar', 'Romanos', 'Rm 8:37', 'Em todas estas coisas somos mais do que vencedores, por aquele que nos amou.', 'Nossa vitória já foi conquistada no Calvário; marche como quem já conhece o final da história. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Rm 8:37 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Rm 8:37. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_083.mp3') ON CONFLICT (dia_ano) DO NOTHING;
