INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (165, 'Dia 165: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 53:5', 'Pelas suas pisaduras fomos sarados.', 'Na cruz de Cristo, não apenas os pecados foram pagos, mas a cura de nossas feridas foi selada. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 53:5 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 53:5. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_165.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (166, 'Dia 166: O Poder de Jeremias no Seu Altar', 'Jeremias', 'Jr 29:11', 'Pois eu bem sei os planos que tenho para vós, diz o Senhor; planos de paz e não de mal.', 'O seu futuro não está entregue ao acaso; está desenhado pelas mãos do Pai. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Jr 29:11 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Jr 29:11. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_166.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (167, 'Dia 167: O Poder de Mateus no Seu Altar', 'Mateus', 'Mt 6:33', 'Buscai primeiro o reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.', 'Alinhe as suas prioridades: coloque Deus no topo e veja as bênçãos se encaixarem. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Mt 6:33 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Mt 6:33. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_167.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (168, 'Dia 168: O Poder de Mateus no Seu Altar', 'Mateus', 'Mt 11:28', 'Vinde a mim, todos os que estais cansados e oprimidos, e eu vos aliviarei.', 'Jesus não te convida para uma religião pesada, Ele te convida para o descanso da graça. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Mt 11:28 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Mt 11:28. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_168.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (169, 'Dia 169: O Poder de João no Seu Altar', 'João', 'Jo 14:6', 'Eu sou o caminho, e a verdade, e a vida; ninguém vem ao Pai senão por mim.', 'Jesus não é uma das opções; Ele é o único caminho seguro para a eternidade. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Jo 14:6 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Jo 14:6. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_169.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (170, 'Dia 170: O Poder de Romanos no Seu Altar', 'Romanos', 'Rm 8:28', 'Todas as coisas cooperam para o bem daqueles que amam a Deus.', 'Até as dores e os desvios serão transformados em bênçãos na mão soberana de Deus. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Rm 8:28 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Rm 8:28. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_170.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (171, 'Dia 171: O Poder de Romanos no Seu Altar', 'Romanos', 'Rm 8:37', 'Em todas estas coisas somos mais do que vencedores, por aquele que nos amou.', 'Nossa vitória já foi conquistada no Calvário; marche como quem já conhece o final da história. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Rm 8:37 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Rm 8:37. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_171.mp3') ON CONFLICT (dia_ano) DO NOTHING;
