INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (237, 'Dia 237: O Poder de Romanos no Seu Altar', 'Romanos', 'Rm 8:37', 'Em todas estas coisas somos mais do que vencedores, por aquele que nos amou.', 'Nossa vitória já foi conquistada no Calvário; marche como quem já conhece o final da história. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Rm 8:37 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Rm 8:37. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_237.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (238, 'Dia 238: O Poder de 2 Coríntios no Seu Altar', '2 Coríntios', '2Co 5:17', 'Se alguém está em Cristo, nova criatura é; as coisas velhas já passaram.', 'O seu passado foi sepultado no mar do esquecimento; viva a novidade de vida. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em 2Co 5:17 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de 2Co 5:17. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_238.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (239, 'Dia 239: O Poder de Gálatas no Seu Altar', 'Gálatas', 'Gl 2:20', 'Já estou crucificado com Cristo; e vivo, não mais eu, mas Cristo vive em mim.', 'A vida vitoriosa nasce do esvaziamento do ego para a plenitude de Cristo. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Gl 2:20 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Gl 2:20. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_239.mp3') ON CONFLICT (dia_ano) DO NOTHING;
