INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (356, 'Dia 356: O Poder de Salmos no Seu Altar', 'Salmos', 'Sl 23:1', 'O Senhor é o meu pastor; nada me faltará.', 'Não é a ausência de dificuldades que nos alegra, mas a presença constante do Bom Pastor. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Sl 23:1 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Sl 23:1. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_356.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (357, 'Dia 357: O Poder de Salmos no Seu Altar', 'Salmos', 'Sl 46:1', 'Deus é o nosso refúgio e fortaleza, socorro bem presente na angústia.', 'Quando o chão tremer, lembre-se de que a Rocha Eterna permanece inabalável. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Sl 46:1 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Sl 46:1. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_357.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (358, 'Dia 358: O Poder de Salmos no Seu Altar', 'Salmos', 'Sl 91:1', 'Aquele que habita no esconderijo do Altíssimo, à sombra do Onipotente descansará.', 'O descanso espiritual não é fuga, é confiança absoluta sob as asas de Deus. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Sl 91:1 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Sl 91:1. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_358.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (359, 'Dia 359: O Poder de Salmos no Seu Altar', 'Salmos', 'Sl 121:1', 'Elevo os meus olhos para os montes: de onde me virá o socorro? O meu socorro vem do Senhor.', 'Tire os olhos das montanhas de problemas e fixe-os no Criador de tudo. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Sl 121:1 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Sl 121:1. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_359.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (360, 'Dia 360: O Poder de Provérbios no Seu Altar', 'Provérbios', 'Pv 3:5', 'Confia no Senhor de todo o teu coração e não te estribes no teu próprio entendimento.', 'A mente humana calcula limites, mas a fé descansa na soberania divina. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Pv 3:5 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Pv 3:5. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_360.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (361, 'Dia 361: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 40:31', 'Os que esperam no Senhor renovarão as suas forças; subirão com asas como águias.', 'A espera em Deus não é tempo perdido; é fortalecimento de asas para voos mais altos. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 40:31 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 40:31. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_361.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (362, 'Dia 362: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 41:10', 'Não temas, porque eu sou contigo; não te assombres, porque eu sou o teu Deus.', 'A solidão se dissipa quando entendemos que a destra fiel de Deus nos sustenta. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 41:10 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 41:10. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_362.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (363, 'Dia 363: O Poder de Isaías no Seu Altar', 'Isaías', 'Is 53:5', 'Pelas suas pisaduras fomos sarados.', 'Na cruz de Cristo, não apenas os pecados foram pagos, mas a cura de nossas feridas foi selada. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Is 53:5 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Is 53:5. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_363.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (364, 'Dia 364: O Poder de Jeremias no Seu Altar', 'Jeremias', 'Jr 29:11', 'Pois eu bem sei os planos que tenho para vós, diz o Senhor; planos de paz e não de mal.', 'O seu futuro não está entregue ao acaso; está desenhado pelas mãos do Pai. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Jr 29:11 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Jr 29:11. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_364.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.devocionais_diarios (dia_ano, titulo, livro_biblia, versiculo_chave, texto_versiculo, reflexao_pastoral, oracao_do_dia, desafio_pratico, audio_url) VALUES (365, 'Dia 365: O Poder de Mateus no Seu Altar', 'Mateus', 'Mt 6:33', 'Buscai primeiro o reino de Deus e a sua justiça, e todas estas coisas vos serão acrescentadas.', 'Alinhe as suas prioridades: coloque Deus no topo e veja as bênçãos se encaixarem. Na caminhada diária da fé, muitas vezes somos confrontados por cansaço, dúvidas e desafios invisíveis. Mas a promessa em Mt 6:33 continua viva hoje na sua vida. Quando você decide entregar o controle ao Senhor e colocar seu clamor diante do altar da IBPM CR, o Céu se move a seu favor. Permaneça firme e veja a salvação do Senhor hoje.', 'Pai Celestial, hoje eu tomo posse da promessa de Mt 6:33. Renova a minha fé, dissipa as incertezas e enche meu coração com a paz do Espírito Santo. Em nome de Jesus, amém.', 'Compartilhe uma palavra de fé com alguém hoje e ore por um milagre na sua família.', 'https://midia.ibpmcr.com.br/audios/devocional_365.mp3') ON CONFLICT (dia_ano) DO NOTHING;
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Estou no meio da minha dor, mas escolho adorar; a cela não decide o meu louvor, a minha fé decide.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Os olhos físicos já não veem o milagre, mas o mesmo Deus que curava antigamente é o mesmo Deus que cura hoje.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O cordeiro mudo que foi levado ao matadouro voltará como leão da tribo de Judá para arrebatar a sua igreja.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Onde abundou o pecado, superabundou a graça; fomos conquistados para as mansões celestiais por um favor que não merecemos.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Deus tem o melhor para cada vida neste lugar; o que ainda não se realizou não foi esquecido por ele.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Ele não vai te chamar pelo teu pecado, ele vai te chamar pelo teu nome.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Não dê ouvidos às vozes que te dizem que você não é capaz; reconheça a voz do seu Mestre e avance.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Quando a sua adoração sobe como perfume, o Pai se inclina para sentir o cheiro; não guarde silêncio diante dele.', 'fe', 'IBPM CR');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A tempestade que você enfrenta hoje não veio para te afundar, veio para te ensinar a andar sobre as águas.', 'ansiedade', 'Mt 14:29');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Descanse o seu coração. Nenhuma oração sincera bate no teto e volta; todas sobem direto ao trono do Pai.', 'ansiedade', 'Ap 8:4');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A ansiedade olha para o relógio; a fé descansa no tempo perfeito de Deus.', 'ansiedade', 'Sl 37:7');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Entregue o fardo pesado no altar. Deus não te chamou para carregar o peso do mundo nas costas.', 'ansiedade', '1Pe 5:7');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A paz de Deus que excede todo o entendimento vai guardar a sua mente contra todo desespero.', 'ansiedade', 'Fp 4:7');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Deus já esteve no seu amanhã e já preparou o livramento que você ainda nem sabe que precisa.', 'ansiedade', 'Dt 31:8');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O medo olha para o tamanho do gigante; a fé olha para o tamanho do Deus que derruba o gigante.', 'medo', '1Sm 17:45');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Não tenha medo do que está à frente, pois Aquele que vai com você é maior do que tudo.', 'medo', 'Js 1:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O perfeito amor de Deus lança fora todo o medo. Você é protegido pelo Sangue do Cordeiro.', 'medo', '1Jo 4:18');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Quando o pavor tentar te paralisar, declare em voz alta: O Senhor é a minha luz e a minha salvação!', 'medo', 'Sl 27:1');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Mil cairão ao teu lado e dez mil à tua direita, mas tu não serás atingido.', 'medo', 'Sl 91:7');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A mão que sustenta as estrelas no firmamento é a mesma que segura firme a sua mão hoje.', 'medo', 'Is 41:13');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Não limite o agir de Deus pelo que seus olhos naturais estão vendo. O invisível de Deus já começou a se mover.', 'fe', 'Hb 11:1');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A fé não torna as coisas mais fáceis, torna as coisas possíveis pelo poder do Altíssimo.', 'fe', 'Mc 9:23');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Basta uma palavra que sai da boca de Deus para mudar a sentença que os homens deram para você.', 'fe', 'Lc 7:7');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Quando a sua fé entra em ação, o impossível perde a força diante do Criador.', 'fe', 'Mt 17:20');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Creia no meio da madrugada; o sol da justiça vai nascer trazendo cura nas suas asas.', 'fe', 'Ml 4:2');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A oração da fé move montanhas, abre mares e derruba muralhas. Persevere!', 'fe', 'Tg 5:15');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A gratidão abre as comportas do céu. Quem louva no pouco será colocado sobre o muito.', 'gratidao', '1Ts 5:18');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Um coração grato atrai a presença manifesta de Deus e silencia a murmuração do inimigo.', 'gratidao', 'Sl 100:4');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Em tudo dai graças, porque a gratidão transforma o pouco em fartura e a dor em sabedoria.', 'gratidao', 'Ef 5:20');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Louvar a Deus antes do milagre acontecer é o maior testemunho de fé que você pode dar.', 'gratidao', 'At 16:25');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Bendize, ó minha alma, ao Senhor, e não te esqueças de nenhum de seus benefícios.', 'gratidao', 'Sl 103:2');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Você não nasceu para ficar caído na beira do caminho. Levante-se, porque a unção de Deus é sobre a sua casa!', 'vitoria', 'Is 60:1');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O que o diabo armou contra você se tornará o palco da maior reviravolta da sua história.', 'vitoria', 'Gn 50:20');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Não há condenação para os que estão em Cristo Jesus. A sua vitória foi selada na cruz!', 'vitoria', 'Rm 8:1');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('A porta que Deus abre para a sua vida, nenhum homem ou potestade do inferno tem poder para fechar.', 'vitoria', 'Ap 3:8');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Você não é vítima das circunstâncias; você é herdeiro da promessa de Cristo!', 'vitoria', 'Rm 8:17');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O leão da tribo de Judá rugiu a favor da sua família. A vitória é nossa!', 'vitoria', 'Ap 5:5');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Deus trabalha no silêncio. Enquanto você chora no altar, Ele já está dando a ordem da sua vitória.', 'desanimo', 'Sl 126:5');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Não desista agora. A última palavra sobre a sua vida quem dá é Aquele que venceu a morte.', 'desanimo', 'Gl 6:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O choro pode durar uma noite inteira, mas a alegria incontível vem pela manhã.', 'desanimo', 'Sl 30:5');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Quando você não tiver forças para orar, o Espírito Santo intercederá por você com gemidos inexprimíveis.', 'desanimo', 'Rm 8:26');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('Deus é especialista em transformar cinzas em coroa de glória e deserto em manancial de águas.', 'desanimo', 'Is 61:3');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('O mesmo Deus que esteve com você nas vitórias de ontem está sustentando você na luta de hoje.', 'desanimo', 'Hb 13:8');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('No Altar da IBPM CR, declaramos: MEDO não governará a sua mente. A glória da segunda casa será maior que a da primeira!', 'medo', 'Ag 2:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('No Altar da IBPM CR, declaramos: FE não governará a sua mente. A glória da segunda casa será maior que a da primeira!', 'fe', 'Ag 2:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('No Altar da IBPM CR, declaramos: GRATIDAO não governará a sua mente. A glória da segunda casa será maior que a da primeira!', 'gratidao', 'Ag 2:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('No Altar da IBPM CR, declaramos: VITORIA não governará a sua mente. A glória da segunda casa será maior que a da primeira!', 'vitoria', 'Ag 2:9');
INSERT INTO public.frases_profeticas (frase, sentimento_tag, referencia_biblica) VALUES ('No Altar da IBPM CR, declaramos: DESANIMO não governará a sua mente. A glória da segunda casa será maior que a da primeira!', 'desanimo', 'Ag 2:9');
